<?php
namespace App\Form\Admin\Clients;
use App\Application\Clients\ClientPhoneData; use Symfony\Component\Form\AbstractType; use Symfony\Component\Form\Extension\Core\Type\{CheckboxType,ChoiceType,HiddenType,TextareaType,TextType}; use Symfony\Component\Form\FormBuilderInterface; use Symfony\Component\OptionsResolver\OptionsResolver;
final class ClientPhoneEntryType extends AbstractType { public function buildForm(FormBuilderInterface $b,array $o):void{$b->add('id',HiddenType::class)->add('type',ChoiceType::class,['label'=>'Tipo','choices'=>['Teléfono fijo'=>'LANDLINE','Celular'=>'MOBILE','Celular personal'=>'PERSONAL_MOBILE','Fax'=>'FAX']])->add('countryCode',TextType::class,['label'=>'País','attr'=>['maxlength'=>5]])->add('areaCode',TextType::class,['label'=>'Lada','required'=>false])->add('number',TextType::class,['label'=>'Número'])->add('extension',TextType::class,['label'=>'Extensión','required'=>false])->add('label',TextType::class,['label'=>'Etiqueta','required'=>false])->add('notes',TextareaType::class,['label'=>'Notas','required'=>false,'attr'=>['rows'=>2]])->add('isPrimary',CheckboxType::class,['label'=>'Principal','required'=>false]);} public function configureOptions(OptionsResolver $r):void{$r->setDefaults(['data_class'=>ClientPhoneData::class]);}}
